#include HEADER
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <string>
#include <vector>
#include <utility>
static const void*volatile escaped;
using Clock=std::chrono::steady_clock;
template<class F>void measure(const char* name,F f){auto a=Clock::now();std::uint64_t sum=f();auto b=Clock::now();std::printf("%s %jd %ju\n",name,static_cast<std::intmax_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(b-a).count()),static_cast<std::uintmax_t>(sum));}
std::uint64_t rand64(std::uint64_t& s){s^=s<<13;s^=s>>7;return s^=s<<17;}
void constructors(){for(int n:{0,1,32,200000}){std::string name="construct_"+std::to_string(n);measure(name.c_str(),[=]{std::uint64_t sum=0;for(int r=0;r<100000;++r){PersistentUnionFind u(n);escaped=u.root;sum+=u.size();if(n)sum+=u.size(r%n);}return sum;});}}
template<int shift>void array_updates(int n,bool two,bool branch,int pattern){std::string name="array_s"+std::to_string(shift)+"_n"+std::to_string(n)+(two?"_two":"_single")+(branch?"_branch":"_current")+"_p"+std::to_string(pattern);std::uint64_t state=9151;std::vector<std::pair<int,int>> pos;int steps=n<100?50000:20000;for(int i=0;i<steps;++i){int a=rand64(state)%n,b=pattern==0?a:pattern==1?((a/16)*16+(rand64(state)%16))%n:rand64(state)%n;pos.emplace_back(a,b);}PersistentArray<int,shift> array(n,0);auto initial=array.root;std::vector<typename PersistentArray<int,shift>::Node*> roots;roots.reserve(steps);measure(name.c_str(),[&]{for(int i=0;i<steps;++i){auto[a,b]=pos[i];auto base=branch?initial:array.root;if(two)array.update_two(base,a,i+1,b,-i-1);else {array.update(base,a,i+1);array.update(b,-i-1);}roots.push_back(array.root);}return roots.size();});std::uint64_t checksum=0;for(int i=0;i<steps;i+=97){auto[a,b]=pos[i];int x=array.get(roots[i],a),y=array.get(roots[i],b);if(y!=-i-1||x!=(a==b?-i-1:i+1))std::abort();checksum+=std::uint32_t(x)+std::uint64_t(std::uint32_t(y));}if(array.get(initial,0)!=0)std::abort();std::printf("%s_check 0 %ju\n",name.c_str(),static_cast<std::uintmax_t>(checksum));}
void queries(int n){PersistentUnionFind uf(n);std::vector<PersistentUnionFind::Node*> roots;for(int stride=1;stride<n;stride*=2)for(int i=0;i+stride<n;i+=stride*2){uf.unite(i,i+stride);if((i&255)==0)roots.push_back(uf.root);}std::uint64_t st=41;struct Op{int a,b;PersistentUnionFind::Node*r;};std::vector<Op> ops;for(int i=0;i<200000;++i)ops.push_back({int(rand64(st)%n),int(rand64(st)%n),roots[rand64(st)%roots.size()]});
for(int mode=0;mode<5;++mode){auto name="query_n"+std::to_string(n)+"_mode"+std::to_string(mode);measure(name.c_str(),[&]{std::uint64_t sum=0;for(const auto&o:ops){if(mode==0)sum+=uf.find(o.a,o.r);else if(mode==1)sum+=uf.same(o.a,o.b,o.r);else if(mode==2)sum+=uf.size(o.a,o.r);else if(mode==3){auto[a,b]=uf.find_with_size(o.a,o.r);sum+=a+std::uint64_t(-b);}else sum+=std::uint32_t(uf.arr.get(o.r,o.a));}return sum;});}
}
void copies(int n){PersistentUnionFind uf(n);for(int i=1;i<100&&i<n;++i)uf.unite(i-1,i);auto name="copy_move_n"+std::to_string(n);measure(name.c_str(),[&]{std::uint64_t sum=0;for(int i=0;i<200000;++i){auto a=uf;auto b=std::move(a);a=b;PersistentUnionFind c(std::move(a));b=std::move(c);escaped=b.root;sum+=b.size();}return sum;});}
template<class T>void from_vector(int n,const T& init,const char*name){std::vector<T> values(n,init);measure(name,[&]{std::uint64_t sum=0;for(int r=0;r<(n<100?10000:5);++r){PersistentArray<T> a(values);escaped=a.root;sum+=a.size();}return sum;});}
void generic_string(){PersistentArray<std::string> a(5000,std::string("012345678901234567890123456789"));std::uint64_t state=423;std::vector<int> pos;for(int i=0;i<10000;++i)pos.push_back(rand64(state)%5000);auto initial=a.root;const std::string value="abcdefghijklmnopqrstuvwxyz0123456789";measure("string_update_get",[&]{std::uint64_t sum=0;for(int i:pos){a.update(i,value);sum+=a.get(i).size();}return sum;});if(a.get(initial,1).size()!=30)std::abort();}
int main(){constructors();for(int n:{32,200000})for(bool two:{false,true})for(bool branch:{false,true})for(int pattern:{0,2})array_updates<4>(n,two,branch,pattern);array_updates<1>(200000,true,false,2);array_updates<8>(200000,true,false,2);queries(32);queries(32768);copies(32);copies(200000);from_vector(32,7,"vector_int_small");from_vector(200000,7,"vector_int_large");from_vector(32,std::string("abcdef"),"vector_string_small");from_vector(5000,std::string("abcdef"),"vector_string_large");generic_string();}

