from pathlib import Path
import subprocess as sp,json,hashlib,statistics,time,fcntl,resource,os,sys
p=Path(__file__).parent;fixtures=Path('/tmp/sirkit_puf_20261022');sha=lambda q:hashlib.sha256(Path(q).read_bytes()).hexdigest()
vs=['baseline','control','final'];ccs={'gcc':['g++'],'clang':['clang++','--gcc-install-dir=/opt/atcoder/gcc/lib/gcc/x86_64-pc-linux-gnu/15.3.0']};builds=[]
main=(p/'main.cpp').read_text().replace('#include "Verify/current/common/fast_io.hpp"',(p/'io.hpp').read_text())
for cc,args in ccs.items():
 for v in vs:
  tu=p/f'{cc}_{v}.cpp';tu.write_text('#define SKIP_RUNTIME_CHECKS\n'+(p/(v+'.hpp')).read_text()+'\n'+main);binary=p/f'{cc}_{v}';cmd=['taskset','-c','10',*args,'-std=c++23','-O2',str(tu),'-o',str(binary)];r=sp.run(cmd,capture_output=True,text=True);assert r.returncode==0,r.stderr;sp.run(['objcopy','--dump-section','.text='+str(binary)+'.text',str(binary)],check=True);builds.append({'compiler':cc,'variant':v,'command':cmd,'source_sha256':sha(p/(v+'.hpp')),'tu_sha256':sha(tu),'binary_sha256':sha(binary),'text_sha256':sha(str(binary)+'.text')})
 print(cc,'builds ready',flush=True)
(p/'builds.json').write_text(json.dumps(builds,indent=2)+'\n')
cases=[fixtures/'official'/n for n in ['random_00.in','max_random_00.in','max_random_01.in','conchon_filliatre_tle_00.in','conchon_filliatre_tle_01.in']]+[fixtures/'custom'/n for n in ['branch_many.in','balanced.in','same_component.in','small_branch.in']]
raw={cc:{v:{c.name:[]for c in cases}for v in vs}for cc in ccs};refs={c.name:(fixtures/'reference_outputs'/(c.name+'.out')).read_bytes().split()for c in cases};outshas={};cache=set();os.sched_setaffinity(0,{10})
with open('/tmp/sirkit_four_hours_20261022/benchmark_geometry.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for rep in range(9):
  for cc in ccs:
   for c in cases:
    order=vs[rep%len(vs):]+vs[:rep%len(vs)]
    for v in order:
     before=resource.getrusage(resource.RUSAGE_CHILDREN);start=time.perf_counter_ns()
     with c.open('rb')as inp:r=sp.run(['taskset','-c','24',str(p/(cc+'_'+v))],stdin=inp,capture_output=True)
     wall=(time.perf_counter_ns()-start)/1e6;after=resource.getrusage(resource.RUSAGE_CHILDREN);assert r.returncode==0 and not r.stderr,(cc,v,c,r.stderr);cpu=1000*((after.ru_utime-before.ru_utime)+(after.ru_stime-before.ru_stime));digest=hashlib.sha256(r.stdout).hexdigest();key=(c.name,digest)
     if key not in cache:assert r.stdout.split()==refs[c.name],(cc,v,c);cache.add(key)
     raw[cc][v][c.name].append({'wall_ms':wall,'child_cpu_ms':cpu});outshas.setdefault(cc,{}).setdefault(v,{})[c.name]=digest
  print('round',rep+1,'passed',flush=True)
  (p/'final_main_partial.json').write_text(json.dumps(raw,indent=2)+'\n')
med={metric:{cc:{v:{c:statistics.median(x[metric]for x in xs)for c,xs in rows.items()}for v,rows in variants.items()}for cc,variants in raw.items()}for metric in ['wall_ms','child_cpu_ms']};ratios={metric:{cc:{v:{c:x/variants['baseline'][c]for c,x in rows.items()}for v,rows in variants.items()}for cc,variants in compilers.items()}for metric,compilers in med.items()}
results={'repetitions':9,'measure_cpu':24,'parent_cpu':10,'raw':raw,'medians':med,'ratios':ratios,'outputs_sha256':outshas,'builds':builds,'inputs':{c.name:{'input_sha256':sha(c),'expected_sha256':sha(fixtures/'reference_outputs'/(c.name+'.out'))}for c in cases}}
