for cc,args in ccs.items():
 for v in vs:
  out=p/('api_'+cc+'_'+v);cmd=['taskset','-c','10',*args,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS','-DSIRKIT_PUF_SOURCE="'+str(p/(v+'.hpp'))+'"',str(source),'-o',str(out)];r=sp.run(cmd,capture_output=True,text=True);assert not r.returncode,r.stderr;builds.append({'compiler':cc,'variant':v,'command':cmd,'source_sha256':hashlib.sha256((p/(v+'.hpp')).read_bytes()).hexdigest(),'binary_sha256':hashlib.sha256(out.read_bytes()).hexdigest()})
 print(cc,'API builds done',flush=True)
raw={cc:{v:{}for v in vs}for cc in ccs};checksums={};os.sched_setaffinity(0,{10})
with open('/tmp/sirkit_four_hours_20261022/benchmark_geometry.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for cc in ccs:
  for mode in ['constructor','same_small','same_large','vector_int_small','vector_int_large','vector_string_small','vector_string_large']:
   rng=random.Random(9451)
   for rep in range(9):
    order=vs[:];rng.shuffle(order)
