     r=sp.run(['taskset','-c','24',str(p/('api_'+cc+'_'+v)),mode],capture_output=True,text=True);assert not r.returncode and not r.stderr,(cc,v,mode,r.stderr);time,checksum=r.stdout.split();assert checksums.setdefault(mode,checksum)==checksum,(mode,v,checksum);raw[cc][v].setdefault(mode,[]).append(float(time))
   med={v:statistics.median(raw[cc][v][mode])for v in vs};print(cc,mode,med,{v:med[v]/med['baseline']for v in vs},flush=True)
med={cc:{v:{k:statistics.median(xs)for k,xs in cs.items()}for v,cs in d.items()}for cc,d in raw.items()};ratios={cc:{v:{k:x/d['baseline'][k]for k,x in cs.items()}for v,cs in d.items()}for cc,d in med.items()};(p/'final_api_results.json').write_text(json.dumps({'repetitions':9,'raw_ms':raw,'median_ms':med,'ratios':ratios,'checksums':checksums,'builds':builds,'fixture_sha256':hashlib.sha256(source.read_bytes()).hexdigest()},indent=2)+'\n')

